#include <iostream>

void moveDisks(int n, char fromTower, char toTower, char auxTower) {
    if (n == 1) {
        std::cout << "Move disk " << n << " from " << fromTower << " to " << toTower << "\n";
    } else {
        moveDisks(n - 1, fromTower, auxTower, toTower);
        std::cout << "Move disk " << n << " from " << fromTower << " to " << toTower << "\n";
        moveDisks(n - 1, auxTower, toTower, fromTower);
    }
}

int main() {
    int n = 3;
    std::cout << "The moves are:\n";
    moveDisks(n, 'A', 'B', 'C');
    return 0;
}

#include <iostream>
#include <array>

constexpr int NUMBER_OF_QUEENS = 8;
std::array<int, NUMBER_OF_QUEENS> queens{};

bool isValid(int row, int column) {
    for (int i = 1; i <= row; ++i) {
        if (queens[row - i] == column ||
            queens[row - i] == column - i ||
            queens[row - i] == column + i) {
            return false;
        }
    }
    return true;
}

bool search(int row) {
    if (row == NUMBER_OF_QUEENS) {
        return true;
    }

    for (int column = 0; column < NUMBER_OF_QUEENS; ++column) {
        queens[row] = column;
        if (isValid(row, column) && search(row + 1)) {
            return true;
        }
    }
    return false;
}

void printResult() {
    std::cout << "---------------------------------\n";
    for (int row = 0; row < NUMBER_OF_QUEENS; ++row) {
        for (int column = 0; column < NUMBER_OF_QUEENS; ++column) {
            std::cout << (column == queens[row] ? "| Q " : "|   ");
        }
        std::cout << "|\n---------------------------------\n";
    }
}

int main() {
    if (search(0)) {
        printResult();
    }
    return 0;
}
